tool.command:
python -c "
import sys
import json
from biomni.tool.synthetic_biology import engineer_bacterial_genome_for_therapeutic_delivery

# Parse arguments
args = {}
i = 1
while i < len(sys.argv):
    if sys.argv[i].startswith('--'):
        key = sys.argv[i][2:]
        if i + 1 < len(sys.argv) and not sys.argv[i + 1].startswith('--'):
            val = sys.argv[i + 1]
            # Type conversion
            if val.lower() == 'true': val = True
            elif val.lower() == 'false': val = False
            else:
                try: val = int(val)
                except:
                    try: val = float(val)
                    except: pass
            args[key] = val
            i += 2
        else:
            args[key] = True
            i += 1
    else:
        i += 1

# Call function
result = engineer_bacterial_genome_for_therapeutic_delivery(**args)

# Write output
output_path = args.get('output', '/dev/stdout')
with open(output_path, 'w') as f:
    if isinstance(result, str):
        f.write(result)
    elif isinstance(result, (dict, list)):
        json.dump(result, f, indent=2, default=str)
    else:
        f.write(str(result))
" --output '$output'
    --bacterial_genome_file '$bacterial_genome_file'
--genetic_parts '$genetic_parts'
